(() => {
  const canvas = document.querySelector('#world');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const ui = {setup:$('#setup'), begin:$('#begin-button'), dialogue:$('#dialogue'), speaker:$('#speaker-name'), role:$('#speaker-label'), text:$('#dialogue-text'), next:$('#dialogue-next'), prompt:$('#interact-prompt'), toast:$('#toast'), questTitle:$('#quest-title'), questCopy:$('#quest-copy'), count:$('#quest-count'), fill:$('#progress-fill'), element:$('#element-label'), symbol:$('#element-symbol'), location:$('#location-name'), map:$('#map-overlay')};
