    {id:'Toph',name:'Toph',role:'EARTHBENDER',x:1285,y:865,color:'#edc39a',coat:'#73966c',accent:'#d6c981',kind:'earth'},
    {id:'Zuko',name:'Zuko',role:'FIREBENDER',x:1710,y:920,color:'#c48863',coat:'#9c5541',accent:'#dfbd72',kind:'fire'},
    {id:'Kai',name:'Kai',role:'YOUR COMPANION',x:950,y:1200,color:'#b77e60',coat:'#4b8790',accent:'#d4e4d8',kind:'romance'},
    {id:'Ren',name:'Ren',role:'YOUR COMPANION',x:1930,y:1160,color:'#c48b69',coat:'#ad6547',accent:'#edc778',kind:'romance'}
  ];
  const blooms=[{x:1015,y:895,got:false},{x:1780,y:1110,got:false},{x:2010,y:760,got:false}];
  const trees=[];let seed=4872;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
  for(let i=0;i<145;i++){const x=120+rand()*(W-240),y=120+rand()*(H-240);if(Math.hypot(x-1300,y-920)<260||Math.hypot(x-510,y-1110)<150)continue;trees.push({x,y,r:15+rand()*22,hue:rand()})}
  const grass=[];for(let i=0;i<670;i++)grass.push({x:rand()*W,y:rand()*H,a:rand()*6.28,l:3+rand()*7,c:rand()});
