  function begin(){selectedElement=selectedElement||'Water';ui.setup.classList.add('hidden');ui.element.textContent=selectedElement.toUpperCase();ui.symbol.textContent=elementData[selectedElement].symbol;ui.symbol.style.color=elementData[selectedElement].color;player.speed=selectedElement==='Air'?230:210;setQuest();showToast(`${selectedElement} is part of your journey. Find Aang at the old arch.`)}
