  function drawVillage(){ctx.fillStyle='#8b7854';ctx.beginPath();ctx.ellipse(515,1115,170,135,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bdac7c';ctx.beginPath();ctx.ellipse(515,1115,151,117,0,0,Math.PI*2);ctx.fill();for(const [x,y] of [[455,1080],[535,1052],[580,1122],[468,1170],[555,1180]]){ctx.fillStyle='#d6c49a';ctx.fillRect(x-18,y-13,36,26);ctx.fillStyle='#855e49';ctx.beginPath();ctx.moveTo(x-25,y-12);ctx.lineTo(x,y-34);ctx.lineTo(x+25,y-12);ctx.closePath();ctx.fill();ctx.fillStyle='#6b5142';ctx.fillRect(x-5,y+2,10,11)}ctx.fillStyle='#f0da9a';ctx.font='12px serif';ctx.fillText('✦  WILLOWBEND',435,1260)}
  function drawArch(){ctx.save();ctx.translate(1370,660);ctx.strokeStyle='#90886a';ctx.lineWidth=18;ctx.beginPath();ctx.arc(0,15,73,Math.PI,0);ctx.stroke();ctx.strokeStyle='#d2c79e';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,15,73,Math.PI,0);ctx.stroke();ctx.fillStyle='#7e8067';ctx.fillRect(-82,13,19,60);ctx.fillRect(63,13,19,60);for(let i=0;i<7;i++){ctx.fillStyle=i%2?'#a29b78':'#c3b991';ctx.fillRect(-72+i*22,-51,18,8)}ctx.restore()}
  function drawShrine(){ctx.save();ctx.translate(2200,520);ctx.fillStyle='#426756';ctx.beginPath();ctx.ellipse(0,35,90,54,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9f9973';ctx.beginPath();ctx.ellipse(0,18,51,28,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#726f58';ctx.fillRect(-40,-39,80,54);ctx.fillStyle='#c6b685';ctx.fillRect(-45,-43,90,9);ctx.fillStyle='#dabd7c';ctx.shadowColor='#f2d594';ctx.shadowBlur=23;ctx.beginPath();ctx.arc(0,-57,10,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#f2d795';ctx.font='11px serif';ctx.fillText('SPIRIT SHRINE',-39,72);ctx.restore()}
  function drawBloom(b){const pulse=1+Math.sin(performance.now()/400+b.x)*.18;ctx.save();ctx.translate(b.x,b.y);ctx.shadowBlur=20;ctx.shadowColor='#f7e6a3';ctx.fillStyle='#f5d894';ctx.beginPath();ctx.arc(0,0,5*pulse,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;for(let i=0;i<5;i++){ctx.save();ctx.rotate(i*Math.PI*2/5);ctx.fillStyle='#f4dfaa';ctx.beginPath();ctx.ellipse(0,-9*pulse,3.5,7*pulse,0,0,Math.PI*2);ctx.fill();ctx.restore()}ctx.fillStyle='#548357';ctx.fillRect(-1,4,2,11);ctx.restore()}
  function drawPerson(x,y,c,playerFlag=false){ctx.save();ctx.translate(x,y);const bounce=playerFlag&&Math.hypot(player.dx,player.dy)>0?Math.sin(player.anim*13)*2:0;ctx.translate(0,bounce);ctx.fillStyle='#182a2c65';ctx.beginPath();ctx.ellipse(0,5,16,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.coat;ctx.beginPath();ctx.moveTo(-11,-1);ctx.quadraticCurveTo(-13,-22,-9,-30);ctx.lineTo(9,-30);ctx.quadraticCurveTo(13,-22,11,-1);ctx.closePath();ctx.fill();ctx.fillStyle=c.accent;ctx.fillRect(-10,-6,20,3);ctx.fillStyle=c.color;ctx.beginPath();ctx.arc(0,-37,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#362f2a';ctx.beginPath();ctx.arc(0,-41,10,Math.PI,Math.PI*2);ctx.fill();if(c.kind==='avatar'){ctx.strokeStyle='#ba7045';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-44);ctx.lineTo(0,-31);ctx.stroke();ctx.fillStyle='#d6ad61';ctx.beginPath();ctx.arc(-7,-51,3,0,Math.PI*2);ctx.fill()}if(c.kind==='fire'){ctx.fillStyle='#8e5547';ctx.beginPath();ctx.arc(-6,-37,5,0,Math.PI*2);ctx.fill()}if(playerFlag){ctx.strokeStyle=elementData[selectedElement]?.color||'#e5d39c';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-16,16,0,Math.PI*2);ctx.stroke();ctx.shadowColor=elementData[selectedElement]?.color;ctx.shadowBlur=13;ctx.fillStyle='#f2d896';ctx.beginPath();ctx.arc(0,-56,2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}ctx.restore()}
  function update(dt){let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(x||y){const m=Math.hypot(x,y);x/=m;y/=m;player.face=Math.atan2(y,x)}player.dx=x*player.speed;player.dy=y*player.speed;player.x=Math.max(40,Math.min(W-40,player.x+player.dx*dt));player.y=Math.max(90,Math.min(H-40,player.y+player.dy*dt));player.anim+=dt;player.bend=Math.max(0,player.bend-dt);const scale=Math.min(vw/1100,vh/670,1.35);camera.x=Math.max(0,Math.min(W-vw/scale,player.x-vw/scale/2));camera.y=Math.max(0,Math.min(H-vh/scale,player.y-vh/scale/2));
    nearby=null;let min=112;for(const n of npcs){const d=dist(player,n);if(d<min){nearby=n;min=d}}if(!done&&window.metAang&&blooms.every(b=>b.got)&&dist(player,{x:2200,y:520})<125){nearby={id:'Shrine',name:'Spirit Shrine',role:'A QUIET PLACE',x:2200,y:520};min=dist(player,nearby)}
    if(nearby&&!ui.dialogue.classList.contains('hidden'))nearby=null;
    if(nearby){const sx=(nearby.x-camera.x)*scale,sy=(nearby.y-camera.y)*scale;ui.prompt.style.display='flex';ui.prompt.style.left=sx+'px';ui.prompt.style.top=(sy-52*scale)+'px';ui.prompt.querySelector('b').textContent=nearby.id==='Shrine'?'Make an offering':nearby.id===selectedRomance?'Talk with '+nearby.name:'Talk'}else ui.prompt.style.display='none';
  }
  function render(){const scale=Math.min(vw/1100,vh/670,1.35);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,vw,vh);ctx.save();ctx.scale(scale,scale);ctx.translate(-camera.x,-camera.y);drawBackground();for(const n of npcs){drawPerson(n.x,n.y,n);ctx.fillStyle='#f2e9ce';ctx.font='11px "DM Sans"';ctx.textAlign='center';ctx.shadowColor='#132b32';ctx.shadowBlur=5;ctx.fillText(n.name,n.x,n.y-66);ctx.shadowBlur=0}drawPerson(player.x,player.y,{coat:'#495a5a',color:'#d9b28a',accent:'#dfc888'},true);if(player.bend>0){ctx.strokeStyle=elementData[selectedElement].color;ctx.globalAlpha=Math.min(.8,player.bend*1.6);ctx.lineWidth=4;ctx.beginPath();ctx.arc(player.x,player.y-15,44+(1-player.bend)*40,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}ctx.restore();requestAnimationFrame(frame)}
  function frame(t){const dt=Math.min(.04,(t-last)/1000||0);last=t;if(!ui.setup.classList.contains('hidden')){camera.x=Math.max(0,player.x-vw/2);camera.y=Math.max(0,player.y-vh/2)}else update(dt);render()}
  const scripts={
    Aang:()=>{if(!window.metAang)return['Aang','THE AVATAR',`Hey! You made it. I’m Aang. The spirit paths have been quiet for a long time—but something is waking up.`,`Those little spirit blooms can help us understand what’s changed. Could you gather three? I’ll be right here by the old arch.`];if(blooms.every(b=>b.got))return['Aang','THE AVATAR','You found all three! Their light feels peaceful. Take them east to the old shrine—maybe the spirits will show us a way forward.'];return['Aang','THE AVATAR','The meadow feels different, doesn’t it? Look for little golden blooms. I can feel their spirit energy from here.'];},
    Katara:()=>['Katara','WATERBENDER','Water teaches us to move with change, not against it. Your '+selectedElement.toLowerCase()+' has its own kind of wisdom. Listen to it.'],
    Sokka:()=>['Sokka','WARRIOR','I drew a map! It’s mostly accurate. The big X means “probably not a pitfall.” Probably. You’ve got this!'],
    Toph:()=>['Toph','EARTHBENDER','You’re lighter on your feet than you look. Breathe deep, feel the ground, and trust your instincts. That’s the good stuff.'],
    Zuko:()=>['Zuko','FIREBENDER','I used to think strength meant never being afraid. It doesn’t. It means choosing what to do next. Keep going.'],
    Kai:()=>['Kai','YOUR COMPANION',`I was hoping you’d come back. The way you bend ${selectedElement.toLowerCase()} is beautiful—like you’re finding your own rhythm.`,`When this adventure gets too big, find me by the lantern trees. We’ll take it one step at a time.`],
    Ren:()=>['Ren','YOUR COMPANION',`I’ve been sketching the way the light follows you. Your ${selectedElement.toLowerCase()} has a color all its own.`,`Save me a place at the shrine? I’d like to see what the spirits show us. Together.`],
    Shrine:()=>['Spirit Shrine','A NEW BEGINNING','The blooms rise into the air. Soft lights drift across the meadow, and a quiet warmth settles in your heart. The spirit paths are open again. Your journey with '+selectedRomance+' is only beginning.']
  };
  function interact(){if(!ui.setup.classList.contains('hidden'))return;if(!ui.dialogue.classList.contains('hidden')){advanceDialogue();return}if(!nearby){showToast('There is no one nearby. Follow the old path.');return}if(nearby.id==='Shrine'){done=true;openDialogue('Shrine');setQuest();return}if(nearby.id==='Aang'&&!window.metAang){window.metAang=true;setQuest()}if(nearby.id==='Aang'&&window.metAang&&blooms.every(b=>b.got)&&!done){showToast('The shrine is east, beyond the golden meadow.');}openDialogue(nearby.id)}
