  function advanceDialogue(){lineIndex++;if(lineIndex>=dialogueLines.length){ui.dialogue.classList.add('hidden');talking=null;setQuest();return}ui.text.textContent=dialogueLines[lineIndex]}
  $('#close-dialogue').addEventListener('click',()=>{ui.dialogue.classList.add('hidden');talking=null;setQuest()});ui.next.addEventListener('click',advanceDialogue);
  function bend(){if(ui.setup.classList.contains('hidden')===false||!ui.dialogue.classList.contains('hidden'))return;player.bend=.7;const effect=elementData[selectedElement];showToast(effect.ability);let found=0;for(const b of blooms){if(!b.got&&dist(player,b)<115){b.got=true;found++}}if(found){setQuest();showToast(found===1?'A spirit bloom joins your collection.':'Spirit blooms join your collection.')}else if(!window.metAang)showToast('A little '+effect.verb+' breeze. Find the Avatar by the stone arch.');}
  function keydown(e){const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k==='e'||k==='enter')interact();if(k===' ')bend();if(k==='escape'){ui.dialogue.classList.add('hidden');ui.map.classList.add('hidden')}if(k==='m')ui.map.classList.toggle('hidden')}
  function keyup(e){keys[e.key.toLowerCase()]=false}addEventListener('keydown',keydown);addEventListener('keyup',keyup);addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
  $('#map-button').addEventListener('click',()=>ui.map.classList.remove('hidden'));$('#close-map').addEventListener('click',()=>ui.map.classList.add('hidden'));ui.map.addEventListener('click',e=>{if(e.target===ui.map)ui.map.classList.add('hidden')});
  document.querySelectorAll('[data-dir]').forEach(b=>{const key={up:'w',down:'s',left:'a',right:'d'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true});['pointerup','pointercancel','pointerleave'].forEach(ev=>b.addEventListener(ev,()=>keys[key]=false))});$('#mobile-action').addEventListener('pointerdown',e=>{e.preventDefault();bend()});$('#mobile-talk').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
  // Tap the nearest visible character or flower to walk toward them.
  canvas.addEventListener('pointerdown',e=>{if(!ui.setup.classList.contains('hidden')||e.target!==canvas)return;const scale=Math.min(vw/1100,vh/670,1.35);player.x=Math.max(40,Math.min(W-40,camera.x+e.clientX/scale));player.y=Math.max(90,Math.min(H-40,camera.y+e.clientY/scale))});
  setQuest();requestAnimationFrame(frame);
})();

